import Anthropic from "@anthropic-ai/sdk";

/** Reads ANTHROPIC_API_KEY from the environment; only use it on the server. */
export const claude = new Anthropic();

export const CLAUDE_MODEL = "claude-opus-5-5";

/**
 * One question, one answer. If the model declines, the API retries on a
 * fallback model in the same call (server-side fallbacks, beta); remove
 * `betas` and `fallbacks` to disable it.
 */
export async function askClaude(prompt: string): Promise<string> {
  const response = await claude.beta.messages.create({
    model: CLAUDE_MODEL,
    max_tokens: 16000,
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",
    messages: [{ role: "user", content: prompt }],
  });
  if (response.stop_reason === "refusal") {
    throw new Error(`Claude declined: ${response.stop_details?.explanation ?? "no explanation"}`);
  }
  return response.content.flatMap((block) => (block.type === "text" ? [block.text] : [])).join("");
}

